import path from 'path';
import type { GuidanceVerification } from '../../types/guidance-verifier';
import { runGuidanceVerifier } from '../../services/GuidanceVerifierRunner';
import { getConfigManager } from '../../services/ConfigManager';
import { errorResult, okResult, type CliCommandResult } from '../envelope';

export const executeContextVerification = async ({
  command,
  packet,
  target,
  projectPath,
  accountId,
  signal,
  outputDirectory,
}: {
  command: string;
  packet: GuidanceVerification;
  target: Record<string, unknown>;
  projectPath: string;
  accountId: string;
  signal?: AbortSignal;
  outputDirectory?: string;
}): Promise<CliCommandResult> => {
  const options = { signal };
  const assertAccount = (): void => {
    if (getConfigManager().getUserId() !== accountId)
      throw new Error('Rivet account changed during verification.');
  };
  const controller = new AbortController();
  const cancel = (): void => controller.abort();
  if (!options.signal) {
    process.once('SIGINT', cancel);
    process.once('SIGTERM', cancel);
  }
  try {
    const report = await runGuidanceVerifier({
      packet,
      projectPath,
      target: target,
      runsDirectory:
        outputDirectory ?? path.join(projectPath, '.rivet', 'verifier-runs'),
      signal: options.signal
        ? AbortSignal.any([controller.signal, options.signal])
        : controller.signal,
    });
    assertAccount();
    if (report.execution === 'completed' && report.status === 'pass')
      return okResult(command, report);
    return errorResult(
      command,
      'OPERATION_FAILED',
      report.execution === 'error'
        ? `Verifier execution failed: ${report.reason}`
        : `Verifier completed with ${report.status} checks`,
      report,
    );
  } finally {
    if (!options.signal) {
      process.removeListener('SIGINT', cancel);
      process.removeListener('SIGTERM', cancel);
    }
  }
};
